body { margin:0; min-height:100vh; color:var(--ink); background:#eef4f8; font-family:'DM Sans', sans-serif; }
body:before { content:''; position:fixed; inset:0; pointer-events:none; background:radial-gradient(circle at 10% 12%, #d8edff 0, transparent 28%), radial-gradient(circle at 92% 88%, #fff0d5 0, transparent 25%); opacity:.8; }
.page-shell { position:relative; width:min(900px, calc(100% - 32px)); margin:44px auto 28px; }
.quiz-card { background:#fff; border:1px solid #e3ebf0; border-radius:24px; box-shadow:0 20px 55px rgba(32,63,91,.12); overflow:hidden; }
.quiz-header { padding:42px 48px 30px; border-bottom:1px solid var(--line); }
.eyebrow,.result-label { color:var(--blue); font-size:11px; font-weight:700; letter-spacing:1.8px; }
h1 { margin:10px 0 9px; font:700 clamp(30px,5vw,44px)/1.1 'Space Grotesk', sans-serif; letter-spacing:-1.5px; }
.quiz-header p { margin:0; color:var(--muted); font-size:15px; }
form { padding:28px 48px 36px; }
.questions { display:grid; gap:22px; }
.question { margin:0; padding:0; border:0; min-width:0; }
legend { display:flex; align-items:flex-start; gap:14px; width:100%; padding:0; font:600 17px/1.4 'Space Grotesk', sans-serif; }
.question-number { flex:none; color:var(--blue); font-size:12px; letter-spacing:1px; padding-top:3px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:14px 0 0 34px; }
