.option:has(input:checked) { border-color:var(--blue); background:var(--pale); color:var(--ink); box-shadow:0 0 0 2px rgba(52,120,246,.08); }
.option input:checked + .custom-radio { border-color:var(--blue); }
.option input:checked + .custom-radio:after { content:''; position:absolute; width:7px; height:7px; border-radius:50%; background:var(--blue); top:50%; left:50%; transform:translate(-50%,-50%); }
.actions { display:flex; align-items:center; gap:20px; margin-top:31px; }
button { border:0; border-radius:10px; padding:14px 22px; color:white; background:var(--blue); font:700 14px 'DM Sans',sans-serif; cursor:pointer; box-shadow:0 7px 15px rgba(52,120,246,.22); transition:.18s; }
button:hover { background:#2365df; transform:translateY(-1px); } button span { margin-left:8px; font-size:18px; vertical-align:-1px; }
.message { margin:0; color:#d46e22; font-size:13px; }
.result { display:flex; align-items:center; gap:18px; min-height:82px; padding:20px 48px; background:#f8fafb; border-top:1px solid var(--line); }
.score { min-width:52px; color:var(--ink); font:700 30px 'Space Grotesk',sans-serif; }
