footer { text-align:center; color:#8695a0; font-size:12px; margin-top:20px; }
@media (max-width:650px) { .page-shell{margin-top:18px;width:calc(100% - 20px)} .quiz-header,form{padding-left:22px;padding-right:22px} .options{grid-template-columns:1fr;margin-left:28px} .result{padding-left:22px;padding-right:22px} }

