const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('message');
const resultText = document.getElementById('result-text');
const answers = { q1: 'jupiter', q2: 'css', q3: 'six' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const formData = new FormData(form);
  const missing = Object.keys(answers).filter((question) => !formData.get(question));

  if (missing.length) {
    message.textContent = 'Please choose an answer for every question.';
    scoreElement.textContent = '';
    scoreElement.removeAttribute('data-score');
    resultText.textContent = '';
    return;
  }

  message.textContent = '';
  let score = 0;
  Object.entries(answers).forEach(([question, answer]) => {
    if (formData.get(question) === answer) score += 1;
  });
  scoreElement.textContent = `${score} / 3`;
  scoreElement.setAttribute('data-score', String(score));
  resultText.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Keep practicing and try again.' : 'Nice effort — review and try once more.';
});

